query:
CREATE (e:MonitoringEvent {
    eventId: "DEMO_EVENT_001",
    eventType: "TAB_SWITCH",
    severity: "MEDIUM",
    details: "Demonstration event for database CRUD testing",
    eventTime: datetime()
})
RETURN e;

MATCH (e:MonitoringEvent {
    eventId: "DEMO_EVENT_001"
})
SET e.severity = "HIGH",
    e.details = "Updated demonstration event"
RETURN e;
